package practice;

/**
 * Summarises one day of readings from one electricity meter, one reading per minute. The billing
 * job stores the summary; the support team reads the longest outage from it.
 */
public class MeterDay {

    /** A minute in which the meter sent nothing. */
    public static final int GAP = -1;

    /** The day's readings in watt-hours, in order; GAP where the meter sent nothing. */
    public interface Readings {
        int size();

        int get(int minute);
    }

    /** What billing stores: energy used, minutes missing, and the longest run of missing minutes. */
    public record Summary(long totalWh, int gaps, int longestOutage) {}

    /** The line the support dashboard shows for one meter. */
    public static String report(String meter, Readings readings) {
        Summary s = summarise(readings);
        return meter + ": " + s.totalWh() + " Wh, " + s.gaps() + " minutes missing, longest outage "
                + s.longestOutage() + " min";
    }

    /** The day's summary. */
    static Summary summarise(Readings readings) {
        long totalWh = 0;
        int gaps = 0;
        int outage = 0;
        int longestOutage = 0;
        int minute = 0;
        while (minute < readings.size()) {
            int wh = readings.get(minute++);
            if (wh == GAP) {
                gaps++;
                outage++;
                longestOutage = Math.max(longestOutage, outage);
                continue;
            }
            outage = 0;
            totalWh += wh;
        }
        return new Summary(totalWh, gaps, longestOutage);
    }
}

package practice;

import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            int g = MeterDay.GAP;
            System.out.println(MeterDay.report("meter-A", readings(15, 20, 25)));
            System.out.println(MeterDay.report("meter-B", readings(g, 10, g, g, 4)));
            System.out.println(MeterDay.report("meter-C", readings(9, g, 1, g, g, g, g)));
            System.out.println("meter-C summary: " + MeterDay.summarise(readings(9, g, 1, g, g, g, g)));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    /** A day of minute readings; the run stops if one day is read far more often than it has minutes. */
    private static MeterDay.Readings readings(int... wh) {
        int[] reads = new int[1];
        return new MeterDay.Readings() {
            @Override public int size() { return wh.length; }
            @Override public int get(int minute) {
                if (++reads[0] > 3 * wh.length + 3) throw new IllegalStateException("minute " + minute + " read again and again");
                return wh[minute];
            }
        };
    }
}

